def gaussian_elimination(A):
    m, n = len(A), len(A[0])
    for i in range(m):
        max_row = i + max(range(i, m), key=lambda r: abs(A[r][i]))
        A[i], A[max_row] = A[max_row], A[i]
        for j in range(n):
            if j != i:
                factor = Fraction(A[j][i], A[i][i])
                for k in range(n):
                    A[j][k] -= factor * A[i][k]
    return A

def matrix_mult(A, B):
    m, n, p = len(A), len(B), len(B[0])
    C = [[Fraction(0) for _ in range(p)] for _ in range(m)]
    for i in range(m):
        for j in range(n):
            for k in range(p):
                C[i][k] += A[i][j] * B[j][k]
    return C

def symplectic_form(cnf):
    n = len(cnf)
    M = [[Fraction(0) for _ in range(n)] for _ in range(n)]
    for clause in cnf:
        for lit1 in clause:
            for lit2 in clause:
                if lit1 != -lit2:
                    i, j = abs(lit1) - 1, abs(lit2) - 1
                    M[i][j] += Fraction(1)
    return gaussian_elimination(M)

def tree_like_resolution_width(cnf):
    n = len(cnf)
    clauses = [set(clause) for clause in cnf]
    stack = []
    while clauses:
        unit_clause = next((c for c in clauses if len(c) == 1), None)
        if not unit_clause:
            return float('inf')
        lit = unit_clause.pop()
        stack.append(lit)
        new_clauses = set()
        for clause in clauses:
            if lit in clause:
                continue
            if -lit in clause:
                new_clauses.add(tuple(sorted(clause - {-lit})))
            else:
                new_clauses.add(tuple(sorted(clause | {lit})))
        clauses = new_clauses
    return len(stack)

